struct ListNode{int val;struct ListNode*next;};
struct ListNode*reverse_k_group(struct ListNode*head,int k){struct ListNode dummy;struct ListNode*group_prev;struct ListNode*kth;struct ListNode*group_next;struct ListNode*prev;struct ListNode*current;struct ListNode*temp;int i;dummy.next=head;group_prev=&dummy;while(1){kth=group_prev;for(i=0;i<k&&kth!=0;i=i+1)kth=kth->next;if(kth==0)break;group_next=kth->next;prev=group_next;current=group_prev->next;while(current!=group_next){temp=current->next;current->next=prev;prev=current;current=temp;}temp=group_prev->next;group_prev->next=kth;group_prev=temp;}return dummy.next;}
int main(void){struct ListNode a[5];struct ListNode*r;int e[5]={2,1,4,3,5};int i;for(i=0;i<5;i=i+1){a[i].val=i+1;a[i].next=i<4?&a[i+1]:0;}r=reverse_k_group(a,2);for(i=0;i<5;i=i+1){if(r==0||r->val!=e[i])return 1;r=r->next;}return 42;}
